//! An in-process fake lightwalletd / zaino: the `CompactTxStreamer` gRPC
//! service over loopback TCP, serving compact blocks, tree states and
//! subtree roots a test hands it (or snapshots from a [`FakeNode`]), with
//! switches for the ways an archival endpoint can misbehave: a stream that
//! skips a block, serves a fork, or hangs. Used by this crate's
//! [`crate::ArtiTorLwdBackend`] tests and by `gygesd`'s. Its server side is
//! generated by `build.rs` from `proto/service.proto` onto the upstream
//! message types, so what it sends is what the real client parses.
//!
//! Like lightwalletd's legacy answer (no `pool_types` requested), the blocks
//! carry no transparent `vin` / `vout`.

use std::collections::{BTreeMap, BTreeSet};
use std::net::SocketAddr;
use std::pin::Pin;
use std::sync::{Arc, Mutex, MutexGuard};

use futures_util::stream::{self, StreamExt as _};
use tokio_stream::wrappers::TcpListenerStream;
use tonic::{Request, Response, Status};
use zcash_client_backend::proto::compact_formats::CompactBlock;
use zcash_client_backend::proto::service::{
    BlockId, BlockRange, ChainSpec, Empty, GetSubtreeRootsArg, LightdInfo, RawTransaction,
    SendResponse, ShieldedProtocol, SubtreeRoot, TreeState, TxFilter,
};
use zcash_protocol::ShieldedPool;
use zcash_protocol::consensus::BlockHeight;

use super::FakeNode;
use crate::display_hash;

#[allow(dead_code, missing_docs, clippy::all)]
mod generated {
    tonic::include_proto!("cash.z.wallet.sdk.rpc");
}

use generated::compact_tx_streamer_server::{CompactTxStreamer, CompactTxStreamerServer};

type BoxStream<T> = Pin<Box<dyn futures_util::Stream<Item = Result<T, Status>> + Send + 'static>>;

/// Subtree roots the fake serves for one pool, as the real endpoint would:
/// index order, raw root bytes, completing block height and hash.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FakeSubtreeRoot {
    pub root: [u8; 32],
    pub end_height: u32,
    /// Internal byte order.
    pub end_hash: [u8; 32],
}

struct LwdState {
    chain_name: String,
    blocks: BTreeMap<u32, CompactBlock>,
    tree_states: BTreeMap<u32, TreeState>,
    subtree_roots: BTreeMap<ShieldedPool, Vec<FakeSubtreeRoot>>,
    /// Heights left out of `GetBlockRange` streams (a lying endpoint).
    omitted: BTreeSet<u32>,
    /// `GetBlockRange` sends this many blocks, then never ends.
    hang_after: Option<usize>,
    /// `SendTransaction` refuses everything with this text.
    reject_broadcasts: Option<String>,
    broadcasts: Vec<Vec<u8>>,
    calls: Vec<String>,
}

/// The running fake. Dropping it stops the server.
pub struct FakeLightwalletd {
    url: String,
    state: Arc<Mutex<LwdState>>,
    task: tokio::task::JoinHandle<()>,
}

impl std::fmt::Debug for FakeLightwalletd {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("FakeLightwalletd")
            .field("url", &self.url)
            .finish()
    }
}

impl Drop for FakeLightwalletd {
    fn drop(&mut self) {
        self.task.abort();
    }
}

impl FakeLightwalletd {
    /// Serve `blocks` (any heights; keyed by `CompactBlock.height`) and
    /// `tree_states` on a loopback port, reporting `chain_name` from
    /// `GetLightdInfo` (`"main"`, `"test"`, or zaino's `"regtest"`).
    pub async fn start(
        chain_name: &str,
        blocks: Vec<CompactBlock>,
        tree_states: Vec<TreeState>,
    ) -> Self {
        let state = Arc::new(Mutex::new(LwdState {
            chain_name: chain_name.to_string(),
            blocks: blocks.into_iter().map(|b| (b.height as u32, b)).collect(),
            tree_states: tree_states
                .into_iter()
                .map(|t| (t.height as u32, t))
                .collect(),
            subtree_roots: BTreeMap::new(),
            omitted: BTreeSet::new(),
            hang_after: None,
            reject_broadcasts: None,
            broadcasts: Vec::new(),
            calls: Vec::new(),
        }));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind loopback");
        let addr: SocketAddr = listener.local_addr().expect("local addr");
        let service = CompactTxStreamerServer::new(Service(state.clone()));
        let task = tokio::spawn(async move {
            let _ = tonic::transport::Server::builder()
                .add_service(service)
                .serve_with_incoming(TcpListenerStream::new(listener))
                .await;
        });
        Self {
            url: format!("http://{addr}"),
            state,
            task,
        }
    }

    /// Snapshot a [`FakeNode`]'s chain: every block in compact form with
    /// the transparent fields stripped (lightwalletd's legacy answer), and
    /// the tree state at every height. Reports `"test"` like the node.
    pub async fn from_node(node: &FakeNode) -> Self {
        let blocks: Vec<CompactBlock> = node
            .compact_chain()
            .into_iter()
            .map(|mut b| {
                for tx in &mut b.vtx {
                    tx.vin.clear();
                    tx.vout.clear();
                }
                b
            })
            .collect();
        let tree_states = (0..=node.tip().0).map(|h| node.tree_state(h)).collect();
        Self::start("test", blocks, tree_states).await
    }

    fn lock(&self) -> MutexGuard<'_, LwdState> {
        self.state.lock().unwrap_or_else(|e| e.into_inner())
    }

    /// `http://127.0.0.1:<port>`.
    pub fn url(&self) -> &str {
        &self.url
    }

    /// Replace the served blocks.
    pub fn set_blocks(&self, blocks: Vec<CompactBlock>) {
        self.lock().blocks = blocks.into_iter().map(|b| (b.height as u32, b)).collect();
    }

    /// Leave `height` out of every `GetBlockRange` stream (the stream jumps
    /// from `height - 1` to `height + 1`).
    pub fn omit_block(&self, height: u32) {
        self.lock().omitted.insert(height);
    }

    /// Serve a different chain from `height` up, as a real fork would look:
    /// block `height` claims a parent other than the served `height - 1`,
    /// its hash and every hash above it change, and the blocks above link
    /// to each other.
    pub fn fork_from(&self, height: u32) {
        let mut st = self.lock();
        let LwdState {
            blocks,
            tree_states,
            ..
        } = &mut *st;
        let mut prev: Option<Vec<u8>> = None;
        for (h, block) in blocks.range_mut(height..) {
            let mut hash = block.hash.clone();
            if let Some(first) = hash.first_mut() {
                *first ^= 0x80;
            }
            match prev.take() {
                Some(p) => block.prev_hash = p,
                None => {
                    if let Some(first) = block.prev_hash.first_mut() {
                        *first ^= 0x80;
                    }
                }
            }
            block.hash = hash.clone();
            if let Some(ts) = tree_states.get_mut(h) {
                ts.hash = display_hash(&hash);
            }
            prev = Some(hash);
        }
    }

    /// `GetBlockRange` sends `n` blocks and then goes silent without ending
    /// the stream (`None` restores normal service).
    pub fn hang_after(&self, n: Option<usize>) {
        self.lock().hang_after = n;
    }

    /// The subtree roots `GetSubtreeRoots` serves for `pool`, index order.
    pub fn set_subtree_roots(&self, pool: ShieldedPool, roots: Vec<FakeSubtreeRoot>) {
        self.lock().subtree_roots.insert(pool, roots);
    }

    /// Make `SendTransaction` refuse everything with `message`.
    pub fn set_reject_broadcasts(&self, message: Option<String>) {
        self.lock().reject_broadcasts = message;
    }

    /// Raw transactions accepted by `SendTransaction`, in order.
    pub fn broadcasts(&self) -> Vec<Vec<u8>> {
        self.lock().broadcasts.clone()
    }

    /// Method names of every request served so far.
    pub fn calls(&self) -> Vec<String> {
        self.lock().calls.clone()
    }
}

struct Service(Arc<Mutex<LwdState>>);

impl Service {
    fn lock(&self, method: &str) -> MutexGuard<'_, LwdState> {
        let mut st = self.0.lock().unwrap_or_else(|e| e.into_inner());
        st.calls.push(method.to_string());
        st
    }
}

fn height_arg(id: Option<BlockId>) -> Result<u32, Status> {
    let id = id.ok_or_else(|| Status::invalid_argument("missing block id"))?;
    if !id.hash.is_empty() {
        return Err(Status::invalid_argument("block hashes are not supported"));
    }
    u32::try_from(id.height).map_err(|_| Status::invalid_argument("height out of range"))
}

#[tonic::async_trait]
impl CompactTxStreamer for Service {
    async fn get_lightd_info(&self, _: Request<Empty>) -> Result<Response<LightdInfo>, Status> {
        let st = self.lock("GetLightdInfo");
        let tip = st.blocks.keys().next_back().copied().unwrap_or(0);
        Ok(Response::new(LightdInfo {
            version: "fake".into(),
            vendor: "gyges-chain test-util".into(),
            taddr_support: true,
            chain_name: st.chain_name.clone(),
            sapling_activation_height: 1,
            consensus_branch_id: "c8e71055".into(),
            block_height: u64::from(tip),
            estimated_height: u64::from(tip),
            lightwallet_protocol_version: "2".into(),
            ..Default::default()
        }))
    }

    async fn get_latest_block(&self, _: Request<ChainSpec>) -> Result<Response<BlockId>, Status> {
        let st = self.lock("GetLatestBlock");
        let Some((h, block)) = st.blocks.iter().next_back() else {
            return Err(Status::unavailable("no blocks"));
        };
        Ok(Response::new(BlockId {
            height: u64::from(*h),
            hash: block.hash.clone(),
        }))
    }

    async fn get_block(&self, req: Request<BlockId>) -> Result<Response<CompactBlock>, Status> {
        let h = height_arg(Some(req.into_inner()))?;
        let st = self.lock("GetBlock");
        st.blocks
            .get(&h)
            .cloned()
            .map(Response::new)
            .ok_or_else(|| Status::not_found(format!("block {h} not found")))
    }

    async fn get_block_range(
        &self,
        req: Request<BlockRange>,
    ) -> Result<Response<BoxStream<CompactBlock>>, Status> {
        let range = req.into_inner();
        let start = height_arg(range.start)?;
        let end = height_arg(range.end)?;
        let st = self.lock("GetBlockRange");
        // lightwalletd streams what it has and ends the stream at a hole or
        // above its tip.
        let mut items = Vec::new();
        for h in start..=end {
            if st.omitted.contains(&h) {
                continue;
            }
            match st.blocks.get(&h) {
                Some(b) => items.push(Ok(b.clone())),
                None => break,
            }
        }
        let hang_after = st.hang_after;
        drop(st);
        let s: BoxStream<CompactBlock> = match hang_after {
            Some(n) => {
                items.truncate(n);
                Box::pin(stream::iter(items).chain(stream::pending()))
            }
            None => Box::pin(stream::iter(items)),
        };
        Ok(Response::new(s))
    }

    async fn get_tree_state(&self, req: Request<BlockId>) -> Result<Response<TreeState>, Status> {
        let h = height_arg(Some(req.into_inner()))?;
        let st = self.lock("GetTreeState");
        st.tree_states
            .get(&h)
            .cloned()
            .map(Response::new)
            .ok_or_else(|| Status::not_found(format!("no tree state at {h}")))
    }

    async fn get_latest_tree_state(
        &self,
        _: Request<Empty>,
    ) -> Result<Response<TreeState>, Status> {
        let st = self.lock("GetLatestTreeState");
        st.tree_states
            .values()
            .next_back()
            .cloned()
            .map(Response::new)
            .ok_or_else(|| Status::not_found("no tree state"))
    }

    async fn get_subtree_roots(
        &self,
        req: Request<GetSubtreeRootsArg>,
    ) -> Result<Response<BoxStream<SubtreeRoot>>, Status> {
        let arg = req.into_inner();
        let pool = match arg.shielded_protocol() {
            ShieldedProtocol::Sapling => ShieldedPool::Sapling,
            ShieldedProtocol::Orchard => ShieldedPool::Orchard,
            ShieldedProtocol::Ironwood => ShieldedPool::Ironwood,
        };
        let st = self.lock("GetSubtreeRoots");
        let roots = st.subtree_roots.get(&pool).cloned().unwrap_or_default();
        let items: Vec<Result<SubtreeRoot, Status>> = roots
            .into_iter()
            .skip(arg.start_index as usize)
            .take(if arg.max_entries == 0 {
                usize::MAX
            } else {
                arg.max_entries as usize
            })
            .map(|r| {
                Ok(SubtreeRoot {
                    root_hash: r.root.to_vec(),
                    completing_block_hash: r.end_hash.to_vec(),
                    completing_block_height: u64::from(r.end_height),
                })
            })
            .collect();
        Ok(Response::new(Box::pin(stream::iter(items))))
    }

    /// Mined transactions only, by txid, with the height lightwalletd
    /// reports; the raw bytes are not kept, so `data` is empty.
    async fn get_transaction(
        &self,
        req: Request<TxFilter>,
    ) -> Result<Response<RawTransaction>, Status> {
        let wanted = req.into_inner().hash;
        let st = self.lock("GetTransaction");
        for (h, block) in &st.blocks {
            if block.vtx.iter().any(|tx| tx.txid == wanted) {
                return Ok(Response::new(RawTransaction {
                    data: vec![],
                    height: u64::from(*h),
                }));
            }
        }
        Err(Status::not_found("transaction not found"))
    }

    async fn send_transaction(
        &self,
        req: Request<RawTransaction>,
    ) -> Result<Response<SendResponse>, Status> {
        let raw = req.into_inner().data;
        let mut st = self.lock("SendTransaction");
        if let Some(reason) = &st.reject_broadcasts {
            return Ok(Response::new(SendResponse {
                error_code: -26,
                error_message: reason.clone(),
            }));
        }
        // lightwalletd answers the node's txid as display hex; the fake
        // does not parse transactions, so it reports the double-SHA256 of
        // the bytes in that place (not a real txid; the backend does not
        // rely on it).
        let txid = {
            use std::hash::{Hash as _, Hasher as _};
            let mut hasher = std::collections::hash_map::DefaultHasher::new();
            raw.hash(&mut hasher);
            let mut out = [0u8; 32];
            out[..8].copy_from_slice(&hasher.finish().to_le_bytes());
            out
        };
        st.broadcasts.push(raw);
        Ok(Response::new(SendResponse {
            error_code: 0,
            error_message: display_hash(&txid),
        }))
    }
}

/// `BlockHeight` of a fake block, for tests.
pub fn h(n: u32) -> BlockHeight {
    BlockHeight::from_u32(n)
}
